{
  "name": "@wavespeed/opencode",
  "version": "0.1.1",
  "description": "WaveSpeed plugin for OpenCode: the hosted WaveSpeed MCP server and the WaveSpeed skill for AI image, video, audio and 3D generation",
  "type": "module",
  "main": "index.ts",
  "exports": {
    ".": "./index.ts"
  },
  "files": [
    "index.ts",
    "v1.ts",
    "v2.ts",
    "shared.ts",
    "skills",
    "README.md",
    "LICENSE"
