  "keywords": [
    "opencode",
    "opencode-plugin",
    "wavespeed",
    "mcp",
    "image-generation",
    "video-generation",
    "audio-generation",
    "ai"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/WaveSpeedAI/wavespeed-opencode.git"
  },
  "homepage": "https://github.com/WaveSpeedAI/wavespeed-opencode#readme",
  "author": {
    "name": "WaveSpeedAI",
    "email": "support@wavespeed.ai",
    "url": "https://wavespeed.ai"
  },
  "scripts": {
    "check": "tsc --noEmit",
    "test": "node --experimental-strip-types --disable-warning=ExperimentalWarning test.mjs"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.19.5",
    "@opencode/plugin": "^2.2.5",
